
UPDATE courses SET
    course_description = '<p><strong> FNS40222 – Certificate IV in Accounting and Bookkeeping</strong> reflects the job roles of workers in the accounting industry, including BAS Agents and contract bookkeepers; and of those employees performing bookkeeping tasks for organisations in a range of industries. It includes preparing and lodging business and instalment activity statements, and providing advice or dealing with the Commissioner on behalf of a taxpayer in relation to activity statements. Individuals in these roles apply theoretical and specialist knowledge and skills to work autonomously, and exercise judgement in completing routine and non-routine activities.</p>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = '14000',
    onshore_tuition_fee = '12000',
    entry_requirements = '<table><tr><td><div class="divTableCell">Academic requirement:<br> Overseas (normal study)</br></div></td><td><div class="divTableCell2">Successful completion of Australian Year 11 or equivalent.</div></td></tr><tr><td><div class="divTableCell">RPL candidates:</div></td><td><div class="divTableCell2">Prior to commencing the RPL process, RPL candidates are required to have relevant work experiences and/or any other evidence to match with the training package requirements.</div></td></tr><tr><td><div class="divTableCell">English requirement:</div></td><td><div class="divTableCell2"><p>A minimum of IELTS 6.0 or equivalent is required.</p><p>For more information regarding the commonly acceptable types of English language proficiency evidence, along with the verification methods, please <a href="https://go.aibt.global/201c19">click here</a></p><p>International Students who do not meet the English language requirements for this course may undertake English Language Intensive Course for Overseas Students (ELICOS) according to the <a href="/get-started/english-requirements/">English Learning Matrix</a>.</p></div></td></tr></table>',
    apply_form = 'https://aibtglobal.edu.au/courses/study/certificate-iv-accounting-bookkeeping/',
    updated_at = NOW()
WHERE cricos_course_code = '111047F';


UPDATE courses SET
    course_description = '<p><strong>FNS50222 – Diploma of Accounting</strong> reflects accounting job roles in financial services and other industries, including tax agents, accounts payable and accounts receivable officers, payroll service providers, and employees performing a range of accounting tasks for organisations in a range of industries. Individuals in these roles apply solutions to a range of often complex problems, and analyse and evaluate information from a variety of sources. They apply initiative to plan, coordinate and evaluate their own work and provide guidance to others within defined guidelines.defined guidelines.</p>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = '14000',
    onshore_tuition_fee = '12000',
    entry_requirements = '<table><tr><td><div class="divTableCellCourseList" style="width: 200px"><h3 class="courseType">Core Subjects</h3></div></td><td><div class="divTableCellCourseList2"></div></td></tr><tr><td><div class="divTableCellCourseList">BSBTEC402</div></td><td><div class="divTableCellCourseList2">Design and produce complex spreadsheets</div></td></tr><tr><td><div class="divTableCellCourseList">FNSACC521</div></td><td><div class="divTableCellCourseList2">Provide financial and business performance information</div></td></tr><tr><td><div class="divTableCellCourseList">FNSACC522</div></td><td><div class="divTableCellCourseList2">Prepare tax documentation for individuals</div></td></tr><tr><td><div class="divTableCellCourseList">FNSACC523</div></td><td><div class="divTableCellCourseList2">Manage budgets and forecasts</div></td></tr><tr><td><div class="divTableCellCourseList">FNSACC524</div></td><td><div class="divTableCellCourseList2">Prepare financial reports for corporate entities</div></td></tr><tr><td><div class="divTableCellCourseList">FNSACC526</div></td><td><div class="divTableCellCourseList2">Implement and maintain internal control procedures</div></td></tr><tr><td><div class="divTableCellCourseList">FNSACC527</div></td><td><div class="divTableCellCourseList2">Provide management accounting information</div></td></tr><tr><td><div class="divTableCellCourseList">BSBCRT511</div></td><td><div class="divTableCellCourseList2">Develop critical thinking in others</div></td></tr><tr><td><div class="divTableCellCourseList">​​*FNSACC601<sup>1</sup></div></td><td><div class="divTableCellCourseList2">Prepare and administer tax documentation for legal entities</div></td></tr><tr><td><div class="divTableCellCourseList">FNSINC611</div></td><td><div class="divTableCellCourseList2">Apply economic principles to work in the financial services industry</div></td></tr><tr><td><div class="divTableCellCourseList">BSBTWK502</div></td><td><div class="divTableCellCourseList2">Manage team effectiveness</div></td></tr><tr><td><div class="divTableCellCourseList"></div></td><td><div class="divTableCellCourseList2"><p><sup>1</sup>This unit included in the Tax Practitioners Board approved course in Australian taxation law: FNSSS00008 Taxation Law for Tax Agent Skill Set (Tax documentation).</p><p>*Pre-requisite unit: FNSACC522 Prepare tax documentation for individuals</p><p>Please note all electives are pre-selected by AIBT.<br/> For more information on the course content, visit:</p><p><a href="https://training.gov.au/Training/Details/FNS50222">Training.gov.au/Training/Details/FNS50222</a></p><table width="668"><tbody><tr><td width="668"><p style="text-align: left"><em>This qualification must be delivered as per the packaging rules, even if a core unit/named elective has been superseded, until such time as the qualification has been updated and this update is reflected on the National Register, training.gov.au, and is listed on the RTO’s Scope of Registration.</em></p><p style="text-align: left"><em>There are many situations where it is considered beneficial for the student to receive the updated training that reflects the current skill needs of the relevant industry so a provider may choose to deliver the updated unit, issue a statement of attainment for those unit/s and then provide credit transfer – by mapping backwards – to the units named within the qualification.</em></p><ul style="text-align: left"><li><em>The VET units need to be deemed ‘equivalent’ for credit transfer to be assigned</em></li><li><em>If the units are ‘not equivalent’ the provider will map the units to identify equivalence in content and learning outcomes (from the updated unit back to the superseded unit)</em></li><li><em>If this is not possible, the provider may need to match the content, but then undertake an RPL process to ascertain competence against each unit of competency.</em>·</li><li><em>This would only need to do this once, then can be used for future decisions in the same circumstances.</em></li></ul><p style="text-align: left"><em>If this still does not ascertain a ‘competent’ result, the student may need to undertake gap training against the destination qualification.</em></p></td></tr></tbody></table></div></td></tr></table>',
    apply_form = 'https://aibtglobal.edu.au/courses/study/diploma-of-accounting-2/',
    updated_at = NOW()
WHERE cricos_course_code = '113810D';


UPDATE courses SET
    course_description = '<p><strong>FNS60222 – Advanced Diploma of Accounting</strong> reflects the role of individuals working in accounting and seeking professional recognition, including tax agents, accounts managers and business analysts; and to employees performing a range of accounts management tasks for organisations in a range of industries. At this level individuals are expected to apply theoretical and technical skills in a range of situations and to display initiative and judgement in planning activities. They have autonomy in performing complex operations and can be responsible for planning, coordinating and evaluating the work of others within broad but generally well-defined parameters.</p>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = '16000',
    onshore_tuition_fee = '14000',
    entry_requirements = '<table><tr><td><div class="divTableCell">Academic requirement:<br> Overseas and domestic (normal study)</br></div></td><td><div class="divTableCell"><p class="ait4">Prior to commencing this qualification an individual must have completed the following qualifications (or equivalent).</p><ul class="ait13"><li>FNS50222 Diploma of Accounting; or its superseded version FNS50217 Diploma of Accounting or equivalent, provided the listed elective unit BSBTEC402 Design and produce complex spreadsheets (or equivalent) has been completed by those seeking to enrol.</li></ul></div></td></tr><tr><td><div class="divTableCell">RPL candidates:</div></td><td><div class="divTableCell2">Prior to commencing the RPL process, RPL candidates are required to have relevant work experiences and/or any other evidence to match with the training package requirements.</div></td></tr><tr><td><div class="divTableCell">English requirement:</div></td><td><div class="divTableCell2"><p>A minimum of IELTS 6.0 or equivalent is required.</p><p>For more information regarding the commonly acceptable types of English language proficiency evidence, along with the verification methods, please <a href="https://go.aibt.global/201c19">click here</a></p><p>International Students who do not meet the English language requirements for this course may undertake English Language Intensive Course for Overseas Students (ELICOS) according to the <a href="/get-started/english-requirements/">English Learning Matrix</a>.</p></div></td></tr></table>',
    apply_form = 'https://aibtglobal.edu.au/courses/study/advanced-diploma-of-accounting-2/',
    updated_at = NOW()
WHERE cricos_course_code = '113811C';


