UPDATE courses SET
    course_description = '<p><strong>BSB50820 – Diploma of Project Management</strong> reflects the role of individuals who apply project management skills and knowledge in a variety of contexts, across a number of industry sectors. The job roles that relate to this qualification may include Project Manager and Project Team Leader.</p> <p>Individuals in these roles have project leadership and management roles and are responsible for achieving project objectives. They possess a sound theoretical knowledge base and use a range of specialised, technical and managerial competencies to initiate, plan, execute and evaluate their own work and/or the work of others.</p> <p><span data-teams="true"> </span></p>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = '14000',
    onshore_tuition_fee = '11000',
    entry_requirements = '<table><tr><td><div class="divTableCell">Academic requirement:<br> Overseas and domestic (normal study)</br></div></td><td><div class="divTableCell2">Successful completion of Australian Year 12 or equivalent.</div></td></tr><tr><td><div class="divTableCell">RPL candidates:</div></td><td><div class="divTableCell2">Prior to commencing the RPL process, RPL candidates are required to have relevant work experiences and/or any other evidence to match with the training package requirements.</div></td></tr><tr><td><div class="divTableCell">English requirement:</div></td><td><div class="divTableCell2"><p>A minimum of IELTS 6.0 or equivalent is required.</p><p>For more information regarding the commonly acceptable types of English language proficiency evidence, along with the verification methods, please <a href="https://go.aibt.global/201c19">click here</a></p><p>International Students who do not meet the English language requirements for this course may undertake English Language Intensive Course for Overseas Students (ELICOS) according to the <a href="/get-started/english-requirements/">English Learning Matrix</a>.</p></div></td></tr></table>',
    apply_form = 'https://aibtglobal.edu.au/courses/study/diploma-project-management/',
    updated_at = NOW()
WHERE cricos_course_code = '104063J';


UPDATE courses SET
    course_description = '<p><strong>BSB60720 – Advanced Diploma in Program Management</strong> reflects the role of individuals who apply specialised knowledge and skills, together with experience in program management across a range of enterprise and industry contexts.</p>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = '13000',
    onshore_tuition_fee = '11000',
    entry_requirements = '<table><tr><td><div class="divTableCell"><strong>Academic requirement:</strong><br> Overseas and domestic (normal study)</br></div></td><td><div class="divTableCell2">Successful completion of Australian Year 12 or equivalent.<p><strong>Entry to this qualification is limited to those who:</strong></p><ul><li>Have completed BSB50820 Diploma of Project Management; or</li><li>Have completed BSB51415 Diploma of Project Management (or a superseded equivalent version); or</li><li>Have completed two years equivalent full-time relevant workplace experience at a significant level within a project or program environment within an enterprise.</li></ul></div></td></tr><tr><td><div class="divTableCell"><strong>RPL candidates:</strong></div></td><td><div class="divTableCell2">Prior to commencing the RPL process, RPL candidates are required to have relevant work experiences and/or any other evidence to match with the training package requirements.</div></td></tr><tr><td><div class="divTableCell"><strong>English requirement:</strong></div></td><td><div class="divTableCell2">A minimum of IELTS 6.0 or equivalent is required.<p>For more information regarding the commonly acceptable types of English language proficiency evidence, along with the verification methods, please<br/> <a href="https://go.aibt.global/201c19" rel="noopener" target="_blank">click here</a>.</p><p>International Students who do not meet the English language requirements for this course may undertake English Language Intensive Course for Overseas Students (ELICOS) according to the<br/> <a href="/get-started/english-requirements/">English Learning Matrix</a>.</p></div></td></tr></table>',
    apply_form = 'https://aibtglobal.edu.au/courses/study/advanced-diploma-program-management/',
    updated_at = NOW()
WHERE cricos_course_code = '104452G';


