UPDATE courses SET
    course_description = '<p><strong>BSB60420 – Advanced Diploma of Leadership and Management </strong> reflects the role of individuals who apply specialised knowledge and skills, together with experience in leadership and management, across a range of enterprise and industry contexts.</p> <p class="ait4">Individuals at this level use initiative and judgement to plan and implement a range of leadership and management functions, with accountability for personal and team outcomes within broad parameters.</p> <p class="ait4">They use cognitive and communication skills to identify, analyse and synthesise information from a variety of sources and transfer their knowledge to others, and creative or conceptual skills to express ideas and perspectives or respond to complex problems.</p>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = '15000',
    onshore_tuition_fee = '12000',
    entry_requirements = '<table><tr><td><div class="divTableCell">Academic requirement:<br> Overseas and domestic (normal study)</br></div></td><td><div class="divTableCell2"> Successful completion of Australian Year 12 or equivalent.<p>Entry to this qualification is limited to those who:Have completed a Diploma or Advanced Diploma from the BSB Training Package (current or superseded equivalent versions).or</p><p>Have two years equivalent full-time relevant workplace experience in an operational or leadership role in an enterprise.</p></div></td></tr><tr><td><div class="divTableCell">RPL candidates:</div></td><td><div class="divTableCell2">Prior to commencing the RPL process, RPL candidates are required to have relevant work experiences and/or any other evidence to match with the training package requirements.</div></td></tr><tr><td><div class="divTableCell">English requirement:</div></td><td><div class="divTableCell2"><p>A minimum of IELTS 6.0 or equivalent is required.</p><p>For more information regarding the commonly acceptable types of English language proficiency evidence, along with the verification methods, please <a href="https://go.aibt.global/201c19">click here</a></p><p>International Students who do not meet the English language requirements for this course may undertake English Language Intensive Course for Overseas Students (ELICOS) according to the <a href="/get-started/english-requirements/">English Learning Matrix</a>.</p></div></td></tr></table>',
    apply_form = 'https://aibtglobal.edu.au/courses/study/advanced-diploma-leadership-management/',
    updated_at = NOW()
WHERE cricos_course_code = '107118H';


