UPDATE courses SET
    course_description = '<p><strong>BSB80120 – Graduate Diploma of Management (Learning)</strong> reflects the roles of individuals who apply highly specialised knowledge and skills in the field of organisational learning and capability development. Individuals in these roles generate and evaluate complex ideas. They also initiate, design and execute major learning and development functions within an organisation. Typically, they would have full responsibility and accountability for the personal output and work of others.</p>',
