UPDATE courses SET
    course_description = '<p><strong>CHC33021 – Certificate III in Individual Support (Ageing) </strong>reflects the role of individuals in the community, home or residential care setting who work under supervision and delegation as a part of a multi-disciplinary team, following an individualised plan to provide person-centred support to people who may require support due to ageing, disability or some other reason. These individuals take responsibility for their own outputs within the scope of their job role and delegation. Workers have a range of factual, technical and procedural knowledge, as well as some theoretical knowledge of the concepts and practices required to provide person-centred support.</p>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = '14000',
