UPDATE courses SET
    course_description = '<p><span data-teams="true"><strong>AUR50126 – Diploma of Automotive Management</strong> reflects the role of individuals who undertake leadership and management roles in the automotive industry. It is suitable for entry into senior management roles in all sectors of the automotive industry.</span></p>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = '15000',
    onshore_tuition_fee = '14000',
    entry_requirements = '<table><tr><td><div class="divTableCellCourseList" style="width: 200px"><h3 class="courseType">Core Subjects</h3></div></td><td><div class="divTableCellCourseList2"></div></td></tr><tr><td><div class="divTableCellCourseList">AURAEA004</div></td><td><div class="divTableCellCourseList2">Manage environmental and sustainability best practice in an automotive workplace</div></td></tr><tr><td><div class="divTableCellCourseList">AURAMA005</div></td><td><div class="divTableCellCourseList2">Manage complex customer issues in an automotive workplace</div></td></tr><tr><td><div class="divTableCellCourseList">AURAMA006</div></td><td><div class="divTableCellCourseList2">Contribute to planning and implementing business improvement in an automotive workplace</div></td></tr><tr><td><div class="divTableCellCourseList">BSBFIM501</div></td><td><div class="divTableCellCourseList2">Manage budgets and financial plans</div></td></tr><tr><td><div class="divTableCellCourseList">BSBMGT502</div></td><td><div class="divTableCellCourseList2">Manage people performance</div></td></tr><tr><td><div class="divTableCellCourseList">BSBWHS501</div></td><td><div class="divTableCellCourseList2">Ensure a safe workplace</div></td></tr><tr><td><div class="divTableCellCourseList"></div></td><td><div class="divTableCellCourseList2"></div></td></tr><tr><td><div class="divTableCellCourseList">AURTTR101</div></td><td><div class="divTableCellCourseList2">Diagnose complex faults in engine management systems</div></td></tr><tr><td><div class="divTableCellCourseList">AURETR037</div></td><td><div class="divTableCellCourseList2">Diagnose complex faults in light vehicle safety systems</div></td></tr><tr><td><div class="divTableCellCourseList">BSBWOR502</div></td><td><div class="divTableCellCourseList2">Lead and manage team effectiveness</div></td></tr><tr><td><div class="divTableCellCourseList">BSBINN502</div></td><td><div class="divTableCellCourseList2">Build and sustain an innovative work environment</div></td></tr><tr><td><div class="divTableCellCourseList">BSBWOR501</div></td><td><div class="divTableCellCourseList2">Manage personal work priorities and professional development</div></td></tr><tr><td><div class="divTableCellCourseList">BSBLED401</div></td><td><div class="divTableCellCourseList2">Develop teams and individuals</div></td></tr><tr><td><div class="divTableCellCourseList"></div></td><td><div class="divTableCellCourseList2">Please note all electives are pre-selected by AIBT.<br/> For more information on the course content, visit <a href="https://training.gov.au/training/details/AUR50126"> https://training.gov.au/training/details/AUR50126</a><table width="668"><tbody><tr><td width="668"><p style="text-align: left"><em>This qualification must be delivered as per the packaging rules, even if a core unit/named elective has been superseded, until such time as the qualification has been updated and this update is reflected on the National Register, training.gov.au, and is listed on the RTO’s Scope of Registration.</em></p><p style="text-align: left"><em>There are many situations where it is considered beneficial for the student to receive the updated training that reflects the current skill needs of the relevant industry so a provider may choose to deliver the updated unit, issue a statement of attainment for those unit/s and then provide credit transfer – by mapping backwards – to the units named within the qualification.</em></p><ul style="text-align: left"><li><em>The VET units need to be deemed ‘equivalent’ for credit transfer to be assigned</em></li><li><em>If the units are ‘not equivalent’ the provider will map the units to identify equivalence in content and learning outcomes (from the updated unit back to the superseded unit)</em></li><li><em>If this is not possible, the provider may need to match the content, but then undertake an RPL process to ascertain competence against each unit of competency.</em>·</li><li><em>This would only need to do this once, then can be used for future decisions in the same circumstances.</em></li></ul><p style="text-align: left"><em>If this still does not ascertain a ‘competent’ result, the student may need to undertake gap training against the destination qualification.</em></p></td></tr></tbody></table></div></td></tr></table>',
    apply_form = 'https://aibtglobal.edu.au/courses/study/diploma-automotive-management/',
    updated_at = NOW()
WHERE cricos_course_code = '120380G';


UPDATE courses SET
    course_description = '<p><strong>AUR40626 – Certificate IV in Automotive Electrical Technology</strong> reflects the role of individuals who work as master diagnostic technicians the automotive service and repair industry; servicing, diagnosing and repairing vehicle electrical systems and components. A range of advanced electrical diagnostic skills and knowledge is necessary, and leadership and supervision of others would be expected.</p>',
