UPDATE courses SET
    course_description = '<p><strong>ICT50220 – Diploma of Information Technology (Telecommunications Network Engineering)</strong> provides the skills and knowledge for an individual to administer and manage information and communications technology (ICT) support in small-to-medium enterprises (SMEs) using a wide range of general ICT technologies.</p> <p class="ait4">Persons working at this level provide a broader rather than specialised ICT support function, applying a wide range of higher level technical skills in ICT areas such as networking, IT support, database development, programming and web development.<br><div class="elementor elementor-17617" data-elementor-id="17617" data-elementor-post-type="elementor_library" data-elementor-type="widget"></div></br></p>',
    total_course_duration = '52 weeks',
